





$("#semester_id").change(function() {
    let semester_id = $(this).val(); 
    console.log(semester_id);
    subject_name(semester_id);
});

// subject_name();
function subject_name(semester_id){


    let sendingData = {
        "action" : "subject_name",
        "semester_id":semester_id
    }

    $.ajax( {
        method: "POST",
        dataType: "JSON",
        // url : "../APi/subject.php",
        url : "../APi/studentview.php",
        data : sendingData,
        success: function(data){

            let status = data.status;
            let response = data.data;
            let html = '';
            let tr = '';

            if(status){

                
                response.forEach( res => {

                   html += `<option value="${res['subject_id']}">${res['subject_name']}</option>`;
                })

                $("#subject_id").append(html);

              
            }else{
                alert("error",response);
            }
           

        },
        error: function(data){

        }
    })

}



$("#class_id").change(function() {
    let semester_id = $(this).val(); 
    // console.log(semester_id);
    resetSelections();
semester_name(semester_id);
    
});
function semester_name(class_id){

    let sendingData = {
        "action" : "semester_name",
        "class_id": class_id
    }

    $.ajax( {
        method: "POST",
        dataType: "JSON",
        url : "../APi/studentview.php",
        data : sendingData,
        success: function(data){
            console.log(data);

            let status = data.status;
            let response = data.data;
            let html = '';
            let tr = '';

            if(status){
                    
                response.forEach( res => {

                   html += `<option value="${res['semester_id']}">${res['semester_name']}</option>`;
                })

                $("#semester_id").append(html);
                


              
            }else{
                // alert("error",response);
            }
           

        },
        error: function(data){

        }
    })

}


function resetSelections() {
 
    $("#semester_id").empty(); 
    $("#semester_id").append('<option value="">Select a semester</option>'); 
}